input.new_string:
if p1 < 0 or p2 < 0:
    raise ValueError("points cannot be negative")
# Check for impossible scores (game would have ended earlier)
if max(p1, p2) > 4 and abs(p1 - p2) > 2:
    raise ValueError("score could not occur because the game would already have ended")
# Check for game won
if max(p1, p2) >= 4 and abs(p1 - p2) >= 2:
    return "Game Player 1" if p1 > p2 else "Game Player 2"
# Deuce or advantage (both have 3+ points)
if p1 >= 3 and p2 >= 3:
    if p1 == p2:
        return "Deuce"
    return "Advantage Player 1" if p1 > p2 else "Advantage Player 2"
# Regular scoring - level scores use "-All" format
if p1 == p2:
    return f"{CALLS[p1]}-All"
return f"{CALLS[p1]}-{CALLS[p2]}"
